"""
demo.py

Self-contained demo page for the fraud detection API, served at GET / by
api.py. Built for a general audience -- no ML vocabulary required. Every
"why" row is a complete, named statement (\"How much was spent \u2014 raised
suspicion a lot\", \"Clue #2 \u2014 lowered suspicion some\") rather than a bare
direction with no subject. Amount and Time get honest descriptive names
since they really do mean what they say; the anonymized V1-V28 features get
an honest numbered placeholder instead of a fabricated meaning, since
there's no honest way to claim we know what an anonymized PCA component
represents. Visitors can also genuinely experiment with the amount field.
Exact technical values remain available behind an opt-in \"for technical
reviewers\" toggle. No separate frontend, no build step, no external files.
"""

DEMO_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>AI Fraud Guard — Live Demo</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&amp;family=IBM+Plex+Sans:wght@400;500;600;700&amp;display=swap" rel="stylesheet">\n<style>\n  :root {\n    --bg-deep: #0B1220;\n    --bg-surface: #141C2F;\n    --bg-surface-alt: #1B2540;\n    --border: #263352;\n    --text-primary: #EEF1F8;\n    --text-muted: #92A0BC;\n    --accent-blue: #57A0DE;\n    --accent-blue-dim: rgba(87, 160, 222, 0.14);\n    --risk-red: #F0565C;\n    --risk-red-dim: rgba(240, 86, 92, 0.14);\n    --safe-green: #3DBB79;\n    --safe-green-dim: rgba(61, 187, 121, 0.14);\n    --radius: 14px;\n    --font-mono: \'IBM Plex Mono\', ui-monospace, \'SF Mono\', \'Cascadia Code\', \'Roboto Mono\', Consolas, monospace;\n    --font-sans: \'IBM Plex Sans\', -apple-system, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n  }\n  * { box-sizing: border-box; }\n  body {\n    margin: 0; background: var(--bg-deep);\n    background-image: radial-gradient(circle at 15% 0%, rgba(87,160,222,0.10), transparent 45%),\n                       radial-gradient(circle at 85% 8%, rgba(61,187,121,0.06), transparent 45%);\n    color: var(--text-primary); font-family: var(--font-sans); min-height: 100vh; -webkit-font-smoothing: antialiased;\n  }\n  a { color: var(--accent-blue); }\n  .wrap { max-width: 820px; margin: 0 auto; padding: 30px 22px 60px; }\n\n  header { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px;\n    padding-bottom: 20px; margin-bottom: 30px; border-bottom: 1px solid var(--border); }\n  .brand { display: flex; align-items: center; gap: 12px; }\n  .brand .icon { font-size: 30px; }\n  .brand h1 { font-size: 20px; font-weight: 700; margin: 0; }\n  .brand .sub { font-size: 13px; color: var(--text-muted); margin-top: 2px; }\n  .status-pill { display: inline-flex; align-items: center; gap: 7px; font-family: var(--font-mono); font-size: 12px; font-weight: 500;\n    padding: 6px 12px; border-radius: 999px; background: var(--safe-green-dim); border: 1px solid rgba(61,187,121,0.35); color: var(--safe-green); }\n  .status-pill.offline { background: var(--risk-red-dim); border-color: rgba(240,86,92,0.35); color: var(--risk-red); }\n  .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }\n  .status-pill.live .dot { animation: pulse 1.8s ease-in-out infinite; }\n  @keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.35; } }\n\n  .story-section { margin: 40px 0; }\n  .kicker { font-family: var(--font-mono); font-size: 11.5px; font-weight: 600; letter-spacing: 0.12em;\n    color: var(--accent-blue); text-transform: uppercase; margin-bottom: 10px; }\n  .section-title { font-size: 24px; font-weight: 700; margin: 0 0 14px; line-height: 1.35; }\n  .lede { font-size: 16px; line-height: 1.7; color: #CBD3E5; margin: 0 0 22px; max-width: 62ch; }\n  hr.divider { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n\n  .stat-row { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 22px; }\n  .stat-card { flex: 1; min-width: 150px; background: var(--bg-surface); border: 1px solid var(--border);\n    border-radius: var(--radius); padding: 18px; text-align: center; }\n  .stat-card .num { font-family: var(--font-mono); font-size: 27px; font-weight: 700; }\n  .stat-card .num.red { color: var(--risk-red); }\n  .stat-card .num.green { color: var(--safe-green); }\n  .stat-card .label { font-size: 12.5px; color: var(--text-muted); margin-top: 6px; line-height: 1.4; }\n\n  .imbalance-bar { height: 30px; border-radius: 8px; background: var(--safe-green); position: relative; margin-bottom: 16px; }\n  .imbalance-fraud-marker { position: absolute; top: -7px; right: 0; height: 44px; width: 5px; background: var(--risk-red); border-radius: 3px; }\n  .imbalance-note { font-size: 14.5px; line-height: 1.65; color: var(--text-muted); margin: 0; }\n  .imbalance-note b { color: var(--text-primary); }\n\n  .big-fact-row { display: flex; gap: 16px; flex-wrap: wrap; margin: 22px 0; }\n  .big-fact { flex: 1; min-width: 220px; background: var(--bg-surface); border: 1px solid var(--border); border-radius: var(--radius);\n    padding: 22px; }\n  .big-fact .ring-wrap { display: flex; align-items: center; gap: 16px; }\n  .ring { width: 64px; height: 64px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center;\n    font-family: var(--font-mono); font-weight: 700; font-size: 14px; }\n  .big-fact .fact-text { font-size: 14.5px; line-height: 1.55; color: #CBD3E5; }\n  .big-fact .fact-text b { color: var(--text-primary); }\n\n  .analogy-box { background: var(--accent-blue-dim); border: 1px solid rgba(87,160,222,0.3); border-radius: var(--radius);\n    padding: 18px 20px; font-size: 15px; line-height: 1.65; color: #DCE6F5; margin: 20px 0; }\n  .analogy-box b { color: var(--text-primary); }\n\n  .grid { display: grid; grid-template-columns: 330px 1fr; gap: 18px; align-items: start; }\n  @media (max-width: 760px) { .grid { grid-template-columns: 1fr; } }\n  .panel { background: var(--bg-surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; }\n  .panel h3.panel-h { font-size: 15px; font-weight: 700; margin: 0 0 8px 0; }\n  .panel .panel-note { font-size: 13.5px; line-height: 1.6; color: var(--text-muted); margin: 0 0 18px; }\n\n  .example-btn { display: block; width: 100%; text-align: left; background: var(--bg-surface-alt); border: 1px solid var(--border);\n    color: var(--text-primary); border-radius: 10px; padding: 14px 16px; margin-bottom: 10px; font-family: var(--font-sans);\n    font-size: 15px; font-weight: 600; cursor: pointer; transition: border-color 0.15s ease, background 0.15s ease; }\n  .example-btn .tag { display: block; font-size: 12px; color: var(--text-muted); margin-top: 3px; font-weight: 400; }\n  .example-btn:hover { border-color: var(--accent-blue); background: var(--accent-blue-dim); }\n  .example-btn:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }\n  .example-btn.selected { border-color: var(--accent-blue); background: var(--accent-blue-dim); }\n\n  .txn-preview { margin-top: 18px; padding-top: 16px; border-top: 1px dashed var(--border); }\n  .txn-preview .placeholder { font-style: italic; color: var(--text-muted); font-size: 14px; }\n\n  .amount-input-label { display: block; font-size: 12.5px; font-weight: 600; color: var(--text-muted); margin-bottom: 8px; }\n  .amount-input-row { display: flex; align-items: center; background: var(--bg-surface-alt); border: 1.5px solid var(--border);\n    border-radius: 10px; padding: 4px 4px 4px 16px; transition: border-color 0.15s ease; }\n  .amount-input-row:focus-within { border-color: var(--accent-blue); }\n  .amount-input-row .currency { font-family: var(--font-mono); font-size: 24px; font-weight: 700; color: var(--text-muted); }\n  .amount-input { flex: 1; min-width: 0; background: none; border: none; outline: none; color: var(--text-primary);\n    font-family: var(--font-mono); font-size: 24px; font-weight: 700; padding: 10px 8px; }\n  .amount-hint { font-size: 12px; color: var(--text-muted); line-height: 1.5; margin: 8px 0 0; }\n  .amount-hint button.reset-link { background: none; border: none; padding: 0; color: var(--accent-blue); font-size: 12px;\n    cursor: pointer; text-decoration: underline; font-family: inherit; }\n  .anon-note { font-size: 13px; color: var(--text-muted); line-height: 1.55; margin-top: 16px; padding-top: 14px; border-top: 1px dashed var(--border); }\n\n  button.score-btn { width: 100%; margin-top: 20px; padding: 15px; border: none; border-radius: 10px; background: var(--accent-blue);\n    color: #071019; font-family: var(--font-sans); font-size: 14.5px; font-weight: 700; cursor: pointer;\n    transition: filter 0.15s ease, transform 0.1s ease; }\n  button.score-btn:hover:not(:disabled) { filter: brightness(1.1); }\n  button.score-btn:active:not(:disabled) { transform: scale(0.99); }\n  button.score-btn:disabled { background: var(--bg-surface-alt); color: var(--text-muted); cursor: not-allowed; }\n\n  .verdict-empty { color: var(--text-muted); font-size: 14.5px; padding: 50px 0; text-align: center; }\n  .checked-with { font-size: 12px; color: var(--text-muted); margin-bottom: 16px; font-family: var(--font-mono); }\n  .checked-with b { color: var(--text-primary); }\n  .verdict-badge-big { display: flex; align-items: center; gap: 14px; padding: 18px 20px; border-radius: var(--radius); margin-bottom: 20px; }\n  .verdict-badge-big.risk { background: var(--risk-red-dim); border: 1px solid rgba(240,86,92,0.4); }\n  .verdict-badge-big.safe { background: var(--safe-green-dim); border: 1px solid rgba(61,187,121,0.4); }\n  .verdict-badge-big .emoji { font-size: 34px; }\n  .verdict-badge-big .msg { font-size: 17px; font-weight: 700; }\n  .verdict-badge-big.risk .msg { color: var(--risk-red); }\n  .verdict-badge-big.safe .msg { color: var(--safe-green); }\n  .verdict-badge-big .sub { font-size: 12.5px; color: var(--text-muted); margin-top: 3px; font-weight: 400; }\n\n  .sure-meter-label { display: flex; justify-content: space-between; font-size: 12px; color: var(--text-muted); margin-bottom: 6px; }\n  .sure-meter { height: 14px; border-radius: 999px; background: var(--bg-surface-alt); overflow: hidden; position: relative; }\n  .sure-meter-fill { height: 100%; width: 0%; border-radius: 999px; transition: width 0.9s cubic-bezier(.2,.7,.3,1); }\n  .sure-meter-fill.risk { background: linear-gradient(90deg, #E0964A, var(--risk-red)); }\n  .sure-meter-fill.safe { background: var(--safe-green); }\n  .sure-pct { text-align: right; font-family: var(--font-mono); font-size: 12px; color: var(--text-muted); margin-top: 6px; }\n\n  .clues { margin-top: 28px; }\n  .clues h4 { font-size: 15px; font-weight: 700; margin: 0 0 4px; }\n  .clues .sub { font-size: 13px; color: var(--text-muted); margin: 0 0 16px; line-height: 1.55; }\n  .clue-row { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }\n  .clue-row .clue-emoji { font-size: 18px; width: 24px; text-align: center; flex-shrink: 0; }\n  .clue-row .clue-body { flex: 1; }\n  .clue-row .clue-name { font-size: 13.5px; font-weight: 700; color: var(--text-primary); }\n  .clue-row .clue-label { font-size: 12.5px; color: var(--text-muted); margin-bottom: 6px; }\n  .clue-bar-track { height: 9px; border-radius: 999px; background: var(--bg-surface-alt); overflow: hidden; }\n  .clue-bar-fill { height: 100%; width: 0%; border-radius: 999px; transition: width 0.6s cubic-bezier(.2,.7,.3,1); }\n  .clue-bar-fill.risk { background: var(--risk-red); }\n  .clue-bar-fill.safe { background: var(--safe-green); }\n\n  details.tech { margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--border); }\n  details.tech summary { font-family: var(--font-mono); font-size: 11.5px; color: var(--text-muted); cursor: pointer; user-select: none; }\n  details.tech .tech-grid { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 10px 22px; font-family: var(--font-mono);\n    font-size: 11px; color: var(--text-muted); }\n  details.tech .tech-grid b { color: var(--text-primary); font-weight: 500; }\n  details.tech pre { margin-top: 10px; font-family: var(--font-mono); font-size: 10.5px; line-height: 1.5; color: var(--text-muted);\n    background: var(--bg-deep); border: 1px solid var(--border); border-radius: 8px; padding: 12px; overflow-x: auto; max-height: 160px; }\n\n  .scanning { display: flex; align-items: center; gap: 10px; color: var(--text-muted); font-size: 14px; padding: 50px 0; justify-content: center; }\n  .spinner { width: 15px; height: 15px; border-radius: 50%; border: 2px solid var(--border); border-top-color: var(--accent-blue);\n    animation: spin 0.7s linear infinite; }\n  @keyframes spin { to { transform: rotate(360deg); } }\n  .error-box { color: var(--risk-red); font-size: 13.5px; padding: 20px 0; text-align: center; }\n\n  footer.page { margin-top: 40px; text-align: center; font-size: 12px; color: var(--text-muted); }\n  footer.page a { color: var(--text-muted); }\n\n  @media (prefers-reduced-motion: reduce) {\n    .sure-meter-fill, .clue-bar-fill, .status-pill.live .dot { transition: none; animation: none; }\n  }\n</style>\n</head>\n<body>\n<div class="wrap">\n\n  <header>\n    <div class="brand">\n      <span class="icon">🛡️</span>\n      <div>\n        <h1>AI Fraud Guard</h1>\n        <div class="sub">A computer program that checks purchases and catches stolen cards</div>\n      </div>\n    </div>\n    <span class="status-pill live" id="statusPill"><span class="dot"></span>LIVE</span>\n  </header>\n\n  <!-- ================= PROBLEM ================= -->\n  <section class="story-section">\n    <div class="kicker">The Problem</div>\n    <h2 class="section-title">Finding 2 fakes hiding in every 1,000 purchases</h2>\n    <p class="lede">Picture a huge pile of card purchases. Almost every single one is a real person buying something real. But every so often, one purchase is someone using a <b>stolen</b> card. Our job is to catch those — without ever accusing an honest shopper.</p>\n\n    <div class="stat-row">\n      <div class="stat-card"><div class="num">284,807</div><div class="label">real purchases we studied</div></div>\n      <div class="stat-card"><div class="num red">492</div><div class="label">were actually stolen cards</div></div>\n      <div class="stat-card"><div class="num">1 in 580</div><div class="label">how rare a fake one is</div></div>\n    </div>\n\n    <div class="imbalance-bar"><div class="imbalance-fraud-marker"></div></div>\n    <p class="imbalance-note">See that tiny red line on the end? That\'s <b>every single fake purchase</b>, drawn next to all the honest ones. If our guard got lazy and said "everyone\'s honest, always" — it would be right <b>998 times out of 1,000</b>. It would also never catch a single thief. Being "right most of the time" isn\'t the same as actually doing the job.</p>\n  </section>\n\n  <hr class="divider">\n\n  <!-- ================= HOW WELL ================= -->\n  <section class="story-section">\n    <div class="kicker">How Well Does It Work?</div>\n    <h2 class="section-title">We tested it on 56,962 purchases it had never seen</h2>\n    <p class="lede">Before trusting any guard, you\'d want to see it tested on cases it doesn\'t already know the answer to. So that\'s exactly what we did.</p>\n\n    <div class="analogy-box">🔔 Think of a smoke alarm. A good one catches real fires <b>and</b> doesn\'t go off every time you make toast. Our guard has to do both jobs at once — catch real thieves, and leave honest shoppers alone.</div>\n\n    <div class="big-fact-row">\n      <div class="big-fact">\n        <div class="ring-wrap">\n          <div class="ring" style="background:conic-gradient(var(--risk-red) 0% 81%, var(--bg-surface-alt) 81% 100%); color:var(--risk-red);">81%</div>\n          <div class="fact-text">Out of <b>98 real</b> stolen-card purchases in the test, our guard caught <b>79</b> of them.</div>\n        </div>\n      </div>\n      <div class="big-fact">\n        <div class="ring-wrap">\n          <div class="ring" style="background:conic-gradient(var(--safe-green) 0% 100%, var(--bg-surface-alt) 100% 100%); color:var(--safe-green);">99.97%</div>\n          <div class="fact-text">Out of <b>56,864 honest</b> purchases, it wrongly blamed only <b>16</b> of them.</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <hr class="divider">\n\n  <!-- ================= TRY IT ================= -->\n  <section class="story-section">\n    <div class="kicker">Try It Yourself</div>\n    <h2 class="section-title">Check a purchase, live — even change the amount</h2>\n    <p class="lede">Start from one of two real purchases below. You can even change the dollar amount yourself and see if it changes our guard\'s mind.</p>\n\n    <div class="grid">\n      <div class="panel">\n        <h3 class="panel-h">Step 1 — Pick a purchase</h3>\n        <p class="panel-note">Both of these are real purchases from our test pile. We already know the true answer for each — you\'re about to see if our guard gets it right.</p>\n\n        <button class="example-btn" id="btnFraud" onclick="loadExample(\'fraud\')">\n          🚨 Start from a real stolen-card purchase\n          <span class="tag">this one really was fraud</span>\n        </button>\n        <button class="example-btn" id="btnLegit" onclick="loadExample(\'legit\')">\n          ✅ Start from a real honest purchase\n          <span class="tag">this one really was normal</span>\n        </button>\n\n        <div class="txn-preview" id="txnPreview">\n          <p class="placeholder">Pick one above to begin.</p>\n        </div>\n\n        <button class="score-btn" id="scoreBtn" disabled onclick="scoreTransaction()">Check This Purchase</button>\n      </div>\n\n      <div class="panel">\n        <h3 class="panel-h">Step 2 — See the decision</h3>\n        <p class="panel-note" id="verdictIntro">Pick a purchase on the left, then press the button, to see what happens.</p>\n        <div id="verdictArea">\n          <div class="verdict-empty">Waiting for you to pick a purchase…</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <footer class="page">\n    Built for an IBM Internship case study · Full technical docs at <a href="/docs">/docs</a>\n  </footer>\n</div>\n\n<script>\nconst EXAMPLES = {\n  fraud: {"Time": 57007.0, "V1": -1.271244192, "V2": 2.462675269, "V3": -2.851395003, "V4": 2.324480065, "V5": -1.37224489, "V6": -0.948195687, "V7": -3.065234362, "V8": 1.166926948, "V9": -2.268770588, "V10": -4.881142927, "V11": 2.255147489, "V12": -4.686386898, "V13": 0.652374669, "V14": -6.174288348, "V15": 0.594379608, "V16": -4.849692387, "V17": -6.536520735, "V18": -3.119093882, "V19": 1.71549442, "V20": 0.560478076, "V21": 0.652941051, "V22": 0.081930976, "V23": -0.221347831, "V24": -0.523582159, "V25": 0.224228162, "V26": 0.756334523, "V27": 0.632800477, "V28": 0.250187093, "Amount": 0.01},\n  legit: {"Time": 160760.0, "V1": -0.674466065, "V2": 1.40810502, "V3": -1.110622054, "V4": -1.328365778, "V5": 1.388996033, "V6": -1.308439067, "V7": 1.885878903, "V8": -0.614232966, "V9": 0.311652212, "V10": 0.650757004, "V11": -0.857784662, "V12": -0.229961446, "V13": -0.199817005, "V14": 0.266371326, "V15": -0.046544168, "V16": -0.74139809, "V17": -0.605616644, "V18": -0.392568188, "V19": -0.162648311, "V20": 0.394321821, "V21": 0.08008424, "V22": 0.810033596, "V23": -0.22432723, "V24": 0.707899237, "V25": -0.135837023, "V26": 0.045102196, "V27": 0.533837219, "V28": 0.291319253, "Amount": 23.0}\n};\nlet currentTxn = null;\nlet currentLabel = null;\n\nasync function loadModelMeta() {\n  try {\n    const res = await fetch(\'/model/info\');\n    if (!res.ok) throw new Error(\'bad response\');\n    await res.json();\n  } catch (e) {\n    const pill = document.getElementById(\'statusPill\');\n    pill.classList.remove(\'live\'); pill.classList.add(\'offline\');\n    pill.innerHTML = \'<span class="dot"></span>OFFLINE\';\n  }\n}\n\nfunction resetAmount() {\n  document.getElementById(\'amountInput\').value = currentTxn.Amount.toFixed(2);\n}\n\nfunction loadExample(which) {\n  currentTxn = EXAMPLES[which];\n  currentLabel = which;\n  document.getElementById(\'btnFraud\').classList.toggle(\'selected\', which === \'fraud\');\n  document.getElementById(\'btnLegit\').classList.toggle(\'selected\', which === \'legit\');\n\n  document.getElementById(\'txnPreview\').innerHTML = `\n    <label class="amount-input-label" for="amountInput">💵 Amount spent — try changing this</label>\n    <div class="amount-input-row">\n      <span class="currency">$</span>\n      <input type="number" id="amountInput" class="amount-input" step="0.01" min="0" value="${currentTxn.Amount.toFixed(2)}">\n    </div>\n    <p class="amount-hint">This is the one detail you can experiment with. (The real amount in this example was $${currentTxn.Amount.toFixed(2)} — <button type="button" class="reset-link" onclick="resetAmount()">put it back</button>)</p>\n    <p class="anon-note">Our guard also looks at 28 other private clues about this purchase (kept secret to protect people\'s information). Those stay fixed from this real example — only the amount above is yours to change.</p>\n  `;\n\n  document.getElementById(\'scoreBtn\').disabled = false;\n  document.getElementById(\'verdictIntro\').textContent = \'Ready — press "Check This Purchase" below.\';\n  document.getElementById(\'verdictArea\').innerHTML = \'<div class="verdict-empty">Waiting for you to press the button…</div>\';\n}\n\nfunction sleep(ms) { return new Promise(r => setTimeout(r, ms)); }\n\nfunction animateCount(el, target, suffix, durationMs) {\n  const start = performance.now();\n  function tick(now) {\n    const t = Math.min(1, (now - start) / durationMs);\n    const eased = 1 - Math.pow(1 - t, 3);\n    el.textContent = (target * eased).toFixed(1) + suffix;\n    if (t < 1) requestAnimationFrame(tick);\n  }\n  requestAnimationFrame(tick);\n}\n\nasync function scoreTransaction() {\n  if (!currentTxn) return;\n  const btn = document.getElementById(\'scoreBtn\');\n  const area = document.getElementById(\'verdictArea\');\n\n  const rawAmount = parseFloat(document.getElementById(\'amountInput\').value);\n  const usedAmount = isNaN(rawAmount) ? currentTxn.Amount : Math.max(0, rawAmount);\n  const payload = Object.assign({}, currentTxn, { Amount: usedAmount });\n\n  btn.disabled = true;\n  document.getElementById(\'verdictIntro\').textContent = \'Our guard is checking…\';\n  area.innerHTML = \'<div class="scanning"><span class="spinner"></span> checking this purchase…</div>\';\n\n  try {\n    const [res] = await Promise.all([\n      fetch(\'/predict\', { method: \'POST\', headers: {\'Content-Type\': \'application/json\'}, body: JSON.stringify(payload) }),\n      sleep(800)\n    ]);\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({detail: res.statusText}));\n      throw new Error(err.detail || \'request failed\');\n    }\n    const data = await res.json();\n    renderVerdict(data, usedAmount);\n  } catch (e) {\n    area.innerHTML = `<div class="error-box">Something went wrong: ${e.message}<br><span style="color:var(--text-muted)">Is the server still running?</span></div>`;\n    document.getElementById(\'verdictIntro\').textContent = \'Something went wrong — see below.\';\n  } finally {\n    btn.disabled = false;\n  }\n}\n\nfunction clueStrength(pct) {\n  if (pct >= 75) return \'a lot\';\n  if (pct >= 40) return \'some\';\n  return \'a little\';\n}\n\nfunction renderVerdict(data, usedAmount) {\n  const pct = data.fraud_probability * 100;\n  const cls = data.flagged ? \'risk\' : \'safe\';\n\n  document.getElementById(\'verdictIntro\').textContent = \'Here\\\'s what our guard decided:\';\n\n  function clueName(feature, idx) {\n    if (feature === \'Amount\') return \'How much was spent\';\n    if (feature === \'Time\') return \'When it happened\';\n    return `Clue #${idx + 1}`;\n  }\n\n  const maxAbs = Math.max(...data.top_factors.map(x => Math.abs(x.contribution)));\n  const cluesHtml = data.top_factors.map((f, idx) => {\n    const width = maxAbs > 0 ? (Math.abs(f.contribution) / maxAbs * 100) : 0;\n    const fcls = f.direction === \'increases_risk\' ? \'risk\' : \'safe\';\n    const emoji = f.direction === \'increases_risk\' ? \'🔺\' : \'🔻\';\n    const verb = f.direction === \'increases_risk\' ? \'raised suspicion\' : \'lowered suspicion\';\n    const name = clueName(f.feature, idx);\n    return `\n      <div class="clue-row">\n        <div class="clue-emoji">${emoji}</div>\n        <div class="clue-body">\n          <div class="clue-name">${name}</div>\n          <div class="clue-label">${verb} ${clueStrength(width)}</div>\n          <div class="clue-bar-track"><div class="clue-bar-fill ${fcls}" style="width:0%" data-w="${width.toFixed(0)}"></div></div>\n        </div>\n      </div>`;\n  }).join(\'\');\n\n  const techFactors = data.top_factors.map(f => `${f.feature} = ${f.value}  (${f.direction})`).join(\'\\n\');\n\n  document.getElementById(\'verdictArea\').innerHTML = `\n    <div class="checked-with">Checked with amount: <b>$${usedAmount.toFixed(2)}</b> (plus the 28 fixed clues from this example)</div>\n\n    <div class="verdict-badge-big ${cls}">\n      <div class="emoji">${data.flagged ? \'🚨\' : \'✅\'}</div>\n      <div>\n        <div class="msg">${data.flagged ? \'This looks like a STOLEN card\' : \'This looks like a HONEST purchase\'}</div>\n        <div class="sub">${data.flagged ? \'Our guard says: stop and double-check this one\' : \'Our guard says: nothing to worry about\'}</div>\n      </div>\n    </div>\n\n    <div class="sure-meter-label"><span>Not sure at all</span><span>Completely sure</span></div>\n    <div class="sure-meter"><div class="sure-meter-fill ${cls}" id="meterFill" style="width:0%"></div></div>\n    <div class="sure-pct" id="probNum">0.0%</div>\n\n    <div class="clues">\n      <h4>Why our guard thinks this</h4>\n      <p class="sub">It checked 30 different clues about this purchase — some are shown by name below, others are private details we just number. Here are the 5 that mattered most this time:</p>\n      ${cluesHtml}\n    </div>\n\n    <details class="tech">\n      <summary>🔬 For technical reviewers — exact numbers</summary>\n      <div class="tech-grid">\n        <span>model: <b>${data.model_name}</b></span>\n        <span>exact probability: <b>${data.fraud_probability}</b></span>\n        <span>decision threshold: <b>${data.threshold_used}</b></span>\n        <span>scored in: <b>${data.scoring_time_ms} ms</b></span>\n      </div>\n      <pre>${techFactors}</pre>\n    </details>\n  `;\n\n  animateCount(document.getElementById(\'probNum\'), pct, \'% sure\', 900);\n  requestAnimationFrame(() => {\n    document.getElementById(\'meterFill\').style.width = Math.min(100, pct) + \'%\';\n    document.querySelectorAll(\'.clue-bar-fill\').forEach(el => {\n      el.style.width = el.dataset.w + \'%\';\n    });\n  });\n}\n\nloadModelMeta();\n</script>\n</body>\n</html>\n'
